      durationMin.hashCode ^
      done.hashCode ^
      deleted.hashCode ^
      repeating.hashCode ^
      listName.hashCode ^
      tags.hashCode ^
      checklistDone.hashCode ^
      checklistTotal.hashCode ^
      subtasks.hashCode ^
      parentId.hashCode ^
      whenLabel.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TaskRow &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          title == other.title &&
          priority == other.priority &&
          dueAt == other.dueAt &&
          allDay == other.allDay &&
          dueLabel == other.dueLabel &&
          overdue == other.overdue &&
          dueToday == other.dueToday &&
          durationMin == other.durationMin &&
          done == other.done &&
          deleted == other.deleted &&
          repeating == other.repeating &&
          listName == other.listName &&
          tags == other.tags &&
          checklistDone == other.checklistDone &&
          checklistTotal == other.checklistTotal &&
          subtasks == other.subtasks &&
          parentId == other.parentId &&
          whenLabel == other.whenLabel;
}

class TaskView {
  final ViewKind kind;
  final String? id;

  const TaskView({required this.kind, this.id});

  @override
  int get hashCode => kind.hashCode ^ id.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TaskView &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          id == other.id;
}

enum ViewKind { inbox, list, tag, filter, completed, trash }
